        const row = [];
        for (let j = 0; j < m; j++) {
            let targetParity;
            if (bestPattern === 0) {
                targetParity = ((i + j) % 2 === 0) ? 1 : 0;
            } else {
                targetParity = ((i + j) % 2 === 0) ? 0 : 1;
            }

            let val = grid[i][j];
            if (val % 2 !== targetParity) {
                val += 1;
            }
            row.push(val);
        }
        output += row.join(' ') + '\n';
    }

    process.stdout.write(output);
}

